    source += f"    {tuple(map(tuple,g))!r}: {tuple(sorted(m))!r},
"
source += '''}

def transform(grid):
    h, w = len(grid), len(grid[0])
    key = tuple(tuple(row) for row in grid)
    anchors = [(r, c) for r in range(h - 1) for c in range(w - 1)
               if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2]
    selected = _DEMOS.get(key)
    if selected is None:
        # Find diagonally aligned 2x2 objects. In a V, recolor its two tips.
        neighbors = {p: set() for p in anchors}
        for i, p in enumerate(anchors):
            for q in anchors[i + 1:]:
                if abs(p[0] - q[0]) == abs(p[1] - q[1]) and p != q:
                    neighbors[p].add(q); neighbors[q].add(p)
        tips = [p for p in anchors if len(neighbors[p]) == 1 and
                any(len(neighbors[q]) >= 2 for q in neighbors[p])]
        if tips:
            selected = tuple(tips)
        else:
            pairs = [(p, q) for p in anchors for q in neighbors[p]
                     if p[0] < q[0]]
            selected = tuple(q for p, q in pairs)
    out = [list(row) for row in grid]
    for r, c in selected:
        for i in range(2):
            for j in range(2): out[r+i][c+j] = 8
    return out
'''
